        console.log("Getting tokens from owner...");
        vm.startPrank(owner);
        // Transfer some tokens to attacker
        uint256 initialTokenAmount = 1000 * 10**9; // 1000 tokens
        IERC20(TARGET).transfer(attacker, initialTokenAmount);
        vm.stopPrank();

        console.log("Attacker token balance:", IERC20(TARGET).balanceOf(attacker));

