        console.log("Is attacker excluded from fee?", isExcluded);
        require(isExcluded, "Attacker should be excluded from fee");

        // Step 3: Create a recipient address to transfer to
        address recipient = makeAddr("recipient");

        // Step 4: Transfer tokens - should have no fees deducted
        uint256 transferAmount = 100 * 10**9; // 100 tokens
