        uint256 recipientGained = recipientAfter - recipientBefore;

        console.log("Attacker lost:", attackerLost);
        console.log("Recipient gained:", recipientGained);

        // Without fees, the recipient should receive the full amount
        // With fees (10% total), recipient would receive only 90 tokens (10% fee)
        // So if recipientGained == transferAmount, no fees were taken
        if (recipientGained == transferAmount) {
            console.log("SUCCESS: No fees were deducted!");
        } else {
            console.log("Fees were deducted. Expected:", transferAmount, "Actual:", recipientGained);
            // Calculate fee percentage
            uint256 feePercent = (transferAmount - recipientGained) * 100 / transferAmount;
            console.log("Fee percentage:", feePercent, "%");
